/* Form: vertical rhythm, error summary, actions footer. */
.form { display: flex; flex-direction: column; gap: var(--s5); min-width: 0; }
.form-errors { border: 1px solid var(--danger); padding: var(--s4); font-size: var(--text-sm); }
.form-errors-title { font-weight: 500; color: var(--danger); margin-bottom: var(--s2); }
.form-errors ul { margin: 0; padding-inline-start: var(--s5); }
.form-errors a { color: var(--foreground); text-decoration: underline; text-underline-offset: 3px; display: inline-block; padding-block: var(--s1); /* 24px minimum target (WCAG 2.5.8) */ }
.form-errors a:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.form-actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s3); padding-top: var(--s4); border-top: 1px solid var(--rule); }

.fieldset { display: grid; gap: var(--s4); margin: 0; padding: var(--s4); border: 1px solid var(--rule); min-width: 0; }
.fieldset-legend { padding: 0 var(--s2); font-size: var(--text-xs); text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); }
.fieldset:disabled { opacity: 0.6; }

/* Checkbox, radio and switch built on Radix (button + data-state). The legacy .choice/.switch classes still style native inputs. */
.checkbox, .radio { appearance: none; flex: none; width: 18px; height: 18px; margin: 0; padding: 0; display: inline-grid; place-items: center; border: 1px solid var(--foreground); background: transparent; color: var(--background); cursor: pointer; transition: background var(--fast); }
.radio { border-radius: var(--round); }
.checkbox[data-state="checked"], .checkbox[data-state="indeterminate"], .radio[data-state="checked"] { background: var(--foreground); }
.checkbox:disabled, .radio:disabled, .sw:disabled { opacity: 0.5; cursor: not-allowed; }
.checkbox[aria-invalid="true"], .radio[aria-invalid="true"] { border-color: var(--danger); }
.checkbox-mark { width: 10px; height: 10px; }
.radio-dot { width: 8px; height: 8px; border-radius: var(--round); background: var(--background); }
.radio-group { display: grid; gap: var(--s3); }
.radio-group[data-orientation="horizontal"] { display: flex; flex-wrap: wrap; gap: var(--s5); }
.sw { flex: none; width: 36px; height: 20px; padding: 0; border: 1px solid var(--foreground); background: transparent; position: relative; cursor: pointer; transition: background var(--fast); }
.sw[data-state="checked"] { background: var(--foreground); }
.sw-thumb { display: block; width: 12px; height: 12px; background: var(--foreground); transform: translateX(calc(3px * var(--dir, 1))); transition: transform var(--base) var(--ease), background var(--fast); }
.sw[data-state="checked"] .sw-thumb { transform: translateX(calc(19px * var(--dir, 1))); background: var(--background); }

/* ─── Choices: checkbox and radio, native inputs redrawn ─── */
.choice { display: inline-flex; align-items: flex-start; gap: var(--s3); cursor: pointer; line-height: 1.4; }
.choice input { appearance: none; flex: none; width: 18px; height: 18px; margin: 1px 0 0; border: 1px solid var(--foreground); background: transparent; position: relative; cursor: pointer; transition: background var(--fast); }
.choice input[type="radio"] { border-radius: var(--round); }
.choice input:checked { background: var(--foreground); }
.choice input[type="checkbox"]:checked::after { content: ""; position: absolute; left: 5px; top: 1px; width: 5px; height: 10px; border: solid var(--background); border-width: 0 2px 2px 0; transform: rotate(45deg); } /* physical: tick geometry, drawn left to right */
.choice input[type="radio"]:checked::after { content: ""; position: absolute; inset: 4px; border-radius: var(--round); background: var(--background); }
.choice input[type="checkbox"]:indeterminate { background: var(--foreground); }
.choice input[type="checkbox"]:indeterminate::after { content: ""; position: absolute; inset-inline: 3px; top: 7px; height: 2px; background: var(--background); }
.choice input:disabled { opacity: 0.5; cursor: not-allowed; }
.choice:has(input:disabled) { color: var(--muted); cursor: not-allowed; }
.choice-group { display: grid; gap: var(--s3); border: 0; padding: 0; margin: 0; min-width: 0; }
.choice-group > legend { padding: 0; margin-bottom: var(--s3); }

/* ─── Form fields ─── */
.field { display: grid; gap: var(--s2); min-width: 0; }
.field-hint { overflow-wrap: anywhere; font-size: var(--text-xs); color: var(--muted); margin-top: var(--s1); }
.input, .select { min-height: var(--control-md); }
.input, .select, .textarea { width: 100%; min-width: 0; background: transparent; border: 1px solid var(--foreground); border-radius: var(--radius); padding: 12px 14px; color: var(--foreground); }
.input::placeholder, .textarea::placeholder { color: var(--muted); }
.input:focus, .select:focus, .textarea:focus { outline: 2px solid var(--accent); outline-offset: 0; }
.input[aria-invalid="true"] { border-color: var(--danger); }
.textarea { resize: vertical; min-height: 120px; line-height: 1.6; }
.input-sm { min-height: var(--control-sm); padding: 6px 10px; font-size: var(--text-sm); }
.input-lg { min-height: var(--control-lg); padding: 14px 18px; }
/* A control at a field's right end (a list picker, a clear button): --s3 in from the edge, the text stops before it. */
.input-wrap { position: relative; min-width: 0; }
.input-wrap > .input { padding-inline-end: var(--s9); }
.input-end { position: absolute; inset-inline-end: var(--s3); top: 50%; transform: translateY(-50%); min-height: var(--s6); min-width: var(--s6); display: inline-grid; place-items: center; }
/* Text edited in place inside a row: no border; padding with a matching negative margin keeps the text in line with its
   neighbours while the focus ring clears it by --s2. The right edge stays put, so the next control keeps its gap. */
.input-bare { display: block; width: calc(100% + var(--s2)); margin: calc(-1 * var(--s2)) 0 calc(-1 * var(--s2)) calc(-1 * var(--s2)); padding: var(--s2); border: 0; background: transparent; resize: none; font: inherit; line-height: inherit; color: inherit; }
.input-bare:focus-visible { outline-offset: 0; }
/* A labelled on/off: a native checkbox drawn as a square switch. */
.switch { display: inline-flex; align-items: center; gap: var(--s3); cursor: pointer; }
.switch input { appearance: none; width: 36px; height: 20px; margin: 0; flex: none; border: 1px solid var(--foreground); position: relative; cursor: pointer; transition: background var(--fast); }
.switch input::after { content: ""; position: absolute; top: 3px; inset-inline-start: 3px; width: 12px; height: 12px; background: var(--foreground); transition: transform var(--base) var(--ease), background var(--fast); }
.switch input:checked { background: var(--foreground); }
.switch input:checked::after { transform: translateX(calc(16px * var(--dir, 1))); background: var(--background); }
.switch input:disabled { opacity: 0.5; cursor: not-allowed; }
/* Settings: label left, control right, a rule between rows. */
.setting { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: var(--s2) var(--s5); padding: var(--s4) 0; }
.setting + .setting { border-top: 1px solid var(--rule); }
.setting > :first-child { display: grid; gap: 2px; }

/* Segmented control: one choice of a few, always visible. */
.seg { display: flex; align-items: center; gap: var(--s2); }
.seg > .muted { margin-inline-end: var(--s1); }
.seg-opt { padding: var(--s1) var(--s3); border: 1px solid var(--rule); color: var(--muted); }
.seg-opt + .seg-opt { margin-inline-start: calc(-1 * var(--s2) - 1px); }
.seg-opt[aria-pressed="true"], .seg-opt[aria-checked="true"] { color: var(--background); background: var(--foreground); border-color: var(--foreground); }
.seg-opt:not([aria-pressed="true"]):not([aria-checked="true"]):hover { color: var(--foreground); }

/* ─── Field states ─── */
.field-error { font-size: var(--text-xs); color: var(--danger); margin-top: var(--s1); }
.field-ok { font-size: var(--text-xs); color: var(--ok); margin-top: var(--s1); }
.input[data-valid="true"] { border-color: var(--ok); }
.input:disabled, .select:disabled, .textarea:disabled { opacity: 0.55; cursor: not-allowed; border-color: var(--rule); }
.input[readonly] { background: var(--wash); border-color: var(--rule); }
.input-group { display: flex; min-width: 0; }
.input-group > .input { flex: 1; }
.input-affix { display: inline-flex; align-items: center; padding: 0 var(--s3); border: 1px solid var(--foreground); color: var(--muted); font-size: var(--text-sm); white-space: nowrap; }
.input-affix:first-child { border-inline-end: 0; }
.input-affix:last-child { border-inline-start: 0; }
.field-required::after { content: " *"; color: var(--danger); }
.form-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: var(--s4); }

/* ─── Buttons: solid (one per view), line (the rest), danger, ghost ─── */
.btn { min-height: var(--control-md); display: inline-flex; align-items: center; justify-content: center; gap: var(--s3); padding: 14px 24px; font-size: var(--text-sm); font-weight: 500; white-space: nowrap; border-radius: var(--radius); transition: transform var(--base), background var(--fast), color var(--fast); }
.btn:active:not(:disabled) { transform: scale(0.98); }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }
.btn-solid { background: var(--foreground); color: var(--background); }
.btn-solid:hover:not(:disabled) { background: var(--ink-2); }
.btn-line { box-shadow: inset 0 0 0 1px var(--foreground); }
.btn-line:hover:not(:disabled) { background: var(--foreground); color: var(--background); }
.btn-danger { box-shadow: inset 0 0 0 1px var(--danger); color: var(--danger); }
.btn-danger:hover:not(:disabled) { background: var(--danger); color: var(--background); }
.btn-ghost { min-height: 0; padding-inline-start: 0; padding-inline-end: 0; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--muted); }
.btn-ghost:hover:not(:disabled) { text-decoration-color: currentColor; }
.btn-sm { min-height: var(--control-sm); padding: 6px 12px; font-size: var(--text-xs); }
.btn-lg { min-height: var(--control-lg); padding: 14px 32px; font-size: var(--text-base); }
.btn-ghost.btn-sm, .btn-ghost.btn-lg { min-height: 0; }
.btn-block { width: 100%; }

/* ─── Loading: a spinner that steps, and a still skeleton ─── */
.spinner { width: 16px; height: 16px; display: inline-block; border: 2px solid var(--rule); border-top-color: var(--foreground); border-radius: var(--round); animation: spin 0.8s steps(8) infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.skeleton { display: block; height: 1em; background: var(--wash-2); }
.skeleton-block { height: var(--s8); }
.skeleton-hatch { background: var(--hatch); box-shadow: inset 0 0 0 1px var(--rule); }

.heading { font-weight: 500; line-height: 1.15; text-wrap: balance; }
.heading-display { font-family: var(--font-display); font-weight: 700; font-size: var(--display-md); letter-spacing: -0.035em; line-height: 0.95; }
.heading-xl { font-family: var(--font-display); font-weight: 700; font-size: var(--display-sm); letter-spacing: -0.03em; }
.heading-lg { font-size: calc(var(--text-lg) * 1.35); }
.heading.heading-md { font-size: var(--text-lg); } /* two classes: typography.css (later in the bundle) also defines .heading-md and .heading-sm with other sizes */
.heading.heading-sm { font-size: var(--text-base); }

.text { max-width: var(--measure); }
.text-xs { font-size: var(--text-xs); } .text-sm { font-size: var(--text-sm); } .text-md { font-size: var(--text-base); } .text-lg { font-size: var(--text-lg); }
.text-muted { color: var(--muted); } .text-danger { color: var(--danger); } .text-success, .text-ok { color: var(--ok); } .text-warning { color: var(--warning); } .text-accent { color: var(--accent-text); }
.text-truncate { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }

/* Block: settings form. */
.block-settings { display: flex; flex-direction: column; gap: var(--s6); width: 100%; max-width: 40rem; padding: var(--s6) var(--s5); }
.block-settings-head { display: flex; flex-direction: column; gap: var(--s2); }
.block-settings-row { display: flex; flex-direction: column; gap: var(--s1); }
.block-settings-row .field-hint { padding-inline-start: var(--s7); }

